  Definition vF (o : Z) (vb : list (Z * Z)) (a : Z) : Prop := ((st1 + o <= a < st1 + o + 24) \/ (st2 + o <= a < st2 + o + 24)) \/ inblk vb a.
  Definition FV1 (a : Z) : Prop := FX a \/ vF 168 (vec_blocks v11) a.
  Definition DV1 : list (Z * Z) := DX ++ vec_blocks v11.
  Definition FV2 (a : Z) : Prop := FV1 a \/ vF 192 (vec_blocks v12) a.
  Definition DV2 : list (Z * Z) := DV1 ++ vec_blocks v12.
  Definition FV3 (a : Z) : Prop := FV2 a \/ vF 216 (vec_blocks v13) a.
  Definition DV3 : list (Z * Z) := DV2 ++ vec_blocks v13.

  Definition vres (o : Z) (vv : Z * Z * Z) (M : mem) : Prop :=
    cell8 SEGS M (st1 + o) (t3a vv) /\ cell8 SEGS M (st1 + o + 8) (t3b vv) /\ cell8 SEGS M (st1 + o + 16) (t3c vv)
    /\ cell8 SEGS M (st2 + o) 0 /\ cell8 SEGS M (st2 + o + 8) 0 /\ cell8 SEGS M (st2 + o + 16) 0.

  Definition maps6 (A : AS MI) (M : mem) : Prop :=
    (umapx MI 24 (nval24 SEGS) A M (st1 + 48) bl21 bc21 e21 /\ umapx MI 24 (nval24 SEGS) A M (st2 + 48) 0 0 [])
    /\ resN A M /\ resX A M.

