  Lemma maps6_keep : forall A A' M M' model (o : Z) (vb : list (Z * Z)) (F' : Z -> Prop),
    maps6 A M -> ainv MI A M model -> eff MI A A' M M' W F' ->
    (forall a, F' a -> vF o vb a) -> 168 <= o -> o + 24 <= 240 ->
    (forall b, In b vb -> In b (state_blocks c1)) ->
    (forall b, In b (state_blocks c2) -> In b (live MI A) -> In b (live MI A')) ->
