    destruct B as (B2 & B3 & B4 & B8 & B9 & Bs);
    unfold base_ok; rewrite Q2, Q8, Q9, !Qs by inl; repeat split; try assumption;
    let r := fresh "r" in let Hr := fresh "Hr" in
    intros r Hr; rewrite Qs; [apply Bs, Hr|]; cbn in Hr; repeat (destruct Hr as [<-|Hr]; [inl|]); destruct Hr.
  Ltac base_fromV' HR' :=
    let Q2 := fresh in let Q8 := fresh in let Q9 := fresh in rreg HR' 2%bv Q2; rreg HR' 8%bv Q8; rreg HR' 9%bv Q9;
    let Qs := fresh in pose proof (syms_id_sound _ _ _ _ [3; 4; 19; 20; 21; 22; 23; 24; 25; 26; 27]%bv HR' eq_refl) as Qs;
    unfold base_ok; rewrite Q2, Q8, Q9, !Qs by inl; repeat split; try assumption;
    let r := fresh "r" in let Hr := fresh "Hr" in
    intros r Hr; rewrite Qs; [| cbn in Hr; repeat (destruct Hr as [<-|Hr]; [inl|]); destruct Hr];
    match goal with Bs : forall r0, In r0 _ -> getr _ r0 = getr R0 r0 |- _ => apply Bs; exact Hr end.
  Ltac nadd := repeat match goal with |- context [alu64 ALU_ADD (Z_to_bv 64 ?a) (Z_to_bv 64 ?k)] => first [rewrite (w_add a k) by lia | rewrite (w_addm a k) by lia] end.

  Lemma vloop1 : forall (k : nat) vb (fx3 : FPState) M model R,
    mstd model -> base_ok R -> 0 < vb -> vb + 20 * (Z.of_nat k + 1) < 2 ^ 64 ->
    getr R 10%bv = Z_to_bv 64 vb -> getr R 11%bv = Z_to_bv 64 (vb + 20 * (Z.of_nat k + 1)) -> getr R 12%bv = Z_to_bv 64 20 ->
    (forall R', base_ok R' -> getr R' 10%bv = Z_to_bv 64 vb -> srealizes SEGS (cfg fx3 R' VX1 M model) K) ->
    srealizes SEGS (cfg fx3 R VL1 M model) K.
Proof using AC L MI ST DEL_STACK fx A0 s R0 M0 model0 sp ret st1 st2 c1 c2 K C.
